let attemptCount = 0;

// A flaky function that fails all 4 times, succeeds on 5th
async function flakyApiCall() {
  attemptCount++;
  console.log(`\n🔄 Attempt ${attemptCount}...`);

  // Simulate failure 4 out of 5 times (80% failure rate)
  if (attemptCount < 5) {
    console.log('  ❌ API FAILED - will retry');
    throw new Error('Simulated API failure');
  }

  console.log('  ✅ API SUCCESS');
  return { data: 'Success!', attempt: attemptCount };
}

