    attempts: 5,
    baseMs: 500,  // 500ms base delay
  };

  const startTime = Date.now();

  try {
    const result = await retry(flakyApiCall, options);
    const elapsed = Date.now() - startTime;

    console.log(`\n🎉 Final result after ${elapsed}ms:`, result);
  } catch (error) {
    const elapsed = Date.now() - startTime;
    console.log('\n💥 All retries exhausted. Total time: ' + elapsed + 'ms');
  }
