/**
 * A simulated flaky function that randomly fails 50% of the time.
 * In real scenarios, this could be an API call, database operation,
 * or any operation that might fail temporarily.
 */
async function flakyOperation(attemptNumber) {
  // Simulate failure 50% of the time
  const shouldFail = Math.random() < 0.5;

  console.log(`Attempt ${attemptNumber}: ${shouldFail ? '❌ Failing' : '✅ Success'}`);

  if (shouldFail) {
    const error = new Error(`Operation failed on attempt ${attemptNumber}`);
    error.code = 'TEMPORARY_FAILURE';
    throw error;
  }

  return `Success on attempt ${attemptNumber}!`;
}

/**
 * Another flaky function that demonstrates exponential backoff.
 * This one succeeds on the 3rd attempt consistently.
 */
async function flakyOperationV2(attemptNumber) {
  console.log(`Attempt ${attemptNumber}: Getting closer...`);

  if (attemptNumber < 3) {
    const error = new Error(`Service unavailable on attempt ${attemptNumber}`);
    error.code = 'SERVICE_UNAVAILABLE';
    throw error;
  }

  console.log(`Attempt ${attemptNumber}: Success!`);
  return 'V2 Success!';
}

/**
 * Demonstrates retry with custom options.
 */
async function flakyOperationWithCustomRetry(attemptNumber) {
  console.log(`Attempt ${attemptNumber}: Probing...`);

  if (attemptNumber < 4) {
    throw new Error(`Unable to connect on attempt ${attemptNumber}`);
  }

  return `Custom retry success on attempt ${attemptNumber}!`;
}

/**
 * Wraps the retry logic to demonstrate success on retry.
 */
async function demonstrateRetry() {
  console.log('='.repeat(50));
  console.log('Example 1: Simple retry with default settings (3 attempts, 100ms base)');
  console.log('='.repeat(50));

  try {
    const result = await retry(flakyOperation);
    console.log('Result:', result);
  } catch (error) {
    console.log('❌ All attempts failed:', error.message);
  }

  console.log('\n'.repeat(2));

  console.log('='.repeat(50));
  console.log('Example 2: Retry with 5 attempts (flaky function that succeeds on 3rd attempt)');
  console.log('='.repeat(50));

  try {
    const result = await retry(flakyOperation, {
      attempts: 5  // Retry up to 5 times
    });
    console.log('Result:', result);
  } catch (error) {
    console.log('❌ All attempts failed:', error.message);
  }

  console.log('\n'.repeat(2));

  console.log('='.repeat(50));
  console.log('Example 3: Custom base delay (500ms) and 5 attempts');
  console.log('='.repeat(50));

  try {
    const result = await retry(flakyOperationWithCustomRetry, {
      attempts: 5,
      baseMs: 500  // Wait 500ms after each failure before retrying
    });
    console.log('Result:', result);
  } catch (error) {
    console.log('❌ All attempts failed:', error.message);
  }

  console.log('\n'.repeat(2));

  console.log('='.repeat(50));
  console.log('Example 4: Demonstrating exponential backoff');
  console.log('='.repeat(50));

  // This shows the timing of the retries
  let timingLogs = [];
  let timingCount = 0;

  try {
    await retry(async () => {
      timingCount++;
      timingLogs.push(`Timing check ${timingCount} - about to throw`);
      throw new Error('Simulated error');
    }, {
      attempts: 5,
      baseMs: 100
    });
  } catch (error) {
    console.log('Timing logs:');
    for (const log of timingLogs) {
      console.log('  ', log);
    }
    console.log('\nNote: Between attempts, the delay follows exponential backoff:');
    console.log('  Attempt 1: delay = 100ms × 2⁰ = 100ms');
    console.log('  Attempt 2: delay = 100ms × 2¹ = 200ms');
    console.log('  Attempt 3: delay = 100ms × 2² = 400ms');
    console.log('  Attempt 4: delay = 100ms × 2³ = 800ms');
  }
}

// Run the example
demonstrateRetry().catch(console.error);

