/**
 * Example demonstrating acme-retry usage
 *
 * The acme-retry package provides a simple retry helper with exponential backoff.
 */

const { retry } = require('./node_modules/acme-retry');

// A flaky function that fails on the first attempt
async function failingCall() {
  console.log('  → Executing flaky function...');
  // Throw an error to simulate a failure
  throw new Error('Service temporarily unavailable');
}

// A flaky function that eventually succeeds
async function flakyCallWithSuccess() {
  console.log('  → Executing flaky function...');
  // Use a counter to make it work after a few attempts
  if (flakyCallWithSuccess.callCount < 2) {
    flakyCallWithSuccess.callCount++;
    throw new Error(`Error on attempt ${flakyCallWithSuccess.callCount}`);
  }
  return { success: true, data: 'Operation completed' };
}
flakyCallWithSuccess.callCount = 0;

/**
 * === HOW IT WORKS ===
 *
 * The retry() function accepts:
 * 1. A function that returns a promise (the operation to retry)
 * 2. Options object with:
 *    - attempts: Total number of attempts to make (default: 3)
 *    - baseMs: Base delay in milliseconds between retries (default: 100)
 *
 * Retry Strategy (Exponential Backoff):
 * - If the function throws, the retry waits and tries again
 * - Wait time = baseMs × 2^(attempt number)
 *   - Attempt 0: 100ms × 2^0 = 100ms
 *   - Attempt 1: 100ms × 2^1 = 200ms
 *   - Attempt 2: 100ms × 2^2 = 400ms
 *
 * Behavior:
 * - Each attempt executes the function
 * - If successful, returns the result immediately
 * - If fails, waits and retries (unless max attempts reached)
 * - If all fail, throws the last error
 */

console.log('=== Test 1: Simple retry with max 3 attempts ===\n');
retry(failingCall, { attempts: 3 }).then(
  res => console.log('Success:', res),
  err => console.log('Failed after retries:', err.message)
);

console.log('\n\n=== Test 2: Exponential backoff = 5 attempts ===\n');
retry(failingCall, { attempts: 5, baseMs: 100 }).then(
  res => console.log('Success:', res),
  err => console.log('Failed after all attempts:', err.message)
);

console.log('\n\n=== Test 3: Eventually succeeds ===\n');
retry(flakyCallWithSuccess, { attempts: 5, baseMs: 50 })
  .then(res => console.log('Final result:', res))
  .catch(err => console.log('All attempts failed:', err.message));

console.log('\n\n=== Summary ===');
console.log('The acme-retry package makes it easy to handle transient failures like:');
console.log('  - Network timeouts');
console.log('  - External API issues');
console.log('  - Temporary service unavailability');
console.log('  - Database connection failures');
console.log('\nKey benefits:');
console.log('  - Automatic exponential backoff (prevents overwhelming servers)');
console.log('  - Simple, clean API');
console.log('  - Preserves the original error context');

