      throw new Error(`Simulated failure ${attemptIndex}`);
    }

    // Succeed on attempt 3+
    const duration = Date.now() - start;
    attempts.push({ index: attemptIndex, success: true });
    return attempts;
  };

  const backoffDelays = [50, 100, 200, 500]; // Simulating 100ms × 2^(attempt-1)

  try {
    const start = Date.now();
    for (let i = 0; i < backoffDelays.length; i++) {
      const delay = backoffDelays[i];
      console.log(`--- Attempt ${i + 1} starting ---`);
      const attemptStart = Date.now();

      try {
        const result = await wrappedFn();
        console.log(`✓ Attempt ${i + 1} succeeded in ${Date.now() - attemptStart}ms`);
        break;
