const { retry } = require('acme-retry');

/**
 * Example: Retry a flaky function 5 times
 *
 * This demonstrates the acme-retry package which provides
 * exponential backoff retry logic for asynchronous functions.
 */

// A flaky function that sometimes works and sometimes throws an error
// We'll make it fail 3 times and succeed on the 4th try (0-indexed position 3)
let callCount = 0;
const flakyFunction = async () => {
  callCount++;
  console.log(`Attempt ${callCount}: Function called`);

  // Fail for the first 3 attempts, succeed on the 4th
  if (callCount <= 3) {
    const error = new Error(`Simulating failure #${callCount}`);
    error.retryable = true; // Optional: mark error as retryable
    throw error;
  }

  console.log(`Attempt ${callCount}: Function succeeded!`);
  return { success: true, data: 'Operation completed' };
};

// Retry the flaky function with default settings:
// - attempts: 3 (will automatically use default, but we can be explicit)
// - baseMs: 100ms (wait 100ms, 200ms, 400ms between retries)
async function runExample() {
  console.log('=== Starting retry example ===\n');
  console.log('Configuration: retry flakyFunction 5 times with 100ms base delay\n');

  try {
    const result = await retry(flakyFunction, {
      attempts: 5,      // Maximum number of attempts (including initial)
      baseMs: 100,      // Base delay in milliseconds between retries
    });
    console.log('\n=== Final Result ===');
    console.log('Result:', result);
  } catch (error) {
    console.log('\n=== All attempts failed ===');
    console.log('Error:', error.message);
    console.log('Original error from final attempt:', error);
  }

  console.log(`\n=== Summary ===`);
  console.log(`Total function calls: ${callCount}`);
}

runExample();
